from pydantic import ValidationError
from linkwatch.config import Site, Settings
assert Site(name=" A ",url=" https://example.org ").name == "A"
assert Site(name=" A ",url=" https://example.org ").url == "https://example.org"
for construct in (lambda: Site(name="",url="https://example.org"),lambda: Site(name="A",url="ftp://example.org"),lambda: Settings(unexpected=True)):
    try: construct()
    except ValidationError: pass
    else: raise AssertionError("validation behavior was lost")
print("whitespace stripping, nonempty name, HTTP scheme and extra-field validation verified")

